import inspect
import robot.api.logger as logger
from functools import wraps
from robot.running import EXECUTION_CONTEXTS
from taf.rfrl.utilities.robot.RobotWrapper import RobotWrapper


def log_as_robot_keyword(function):
    @wraps(function)
    def logged_function(*args, **kwargs):
        params = list(inspect.signature(function).parameters)
        ignore_self = params and params[0] == "self"
        args_for_print = [f"{arg}" for index, arg in enumerate(args) if not (ignore_self and index == 0)]
        kwargs_for_print = [f"{kwarg}={value}" for kwarg, value in kwargs.items()]
        arguments = " | ".join(args_for_print + kwargs_for_print)
        function_formatted_name = " ".join([word.title() for word in function.__name__.split("_")])
        is_method_called_directly_in_robot_file = _check_whether_method_called_directly_in_robot_file()
        if EXECUTION_CONTEXTS.current and not is_method_called_directly_in_robot_file:
            with RobotWrapper(f"{function_formatted_name}", "kw"):
                logger.info(f"Arguments: [{arguments}]", html=True)
                result = function(*args, **kwargs)
                logger.info(f"Return: {result}", html=True)
            return result
        return function(*args, **kwargs)

    return logged_function


def _check_whether_method_called_directly_in_robot_file():
    stack = inspect.stack()
    caller_frame = stack[2]  # stack[0] is this function, stack[1] is the decorator, stack[2] is the caller
    if 'robot/running/librarykeywordrunner.py' in caller_frame.filename:
        return True
    return False
